// TH18 v1.00a Stage 4 MainSub01 second group S:880-892, shared enemy Cir01 S:68-139.
// Eight Cir01 spawn in four +/- pairs at local 0/40/80/120.
const TIME_LIMIT: int = 600;      // 120 opening buffer + 480 local (360 source window + 120 tail)
const OPENING_BUFFER: int = 120;
const TH18_RING_BALL2: int = 464;

// Cir01 movement, source S:78-80:
//   moveVel(pi/2, 4.4); moveVelTime(80, mode0, pi/2, 0.4);
//   moveEllipseRel(theta0, omega=2deg, r=10, d=0, beta=ABS_ANGLE=pi/2, ratio=0).
// ABS is the 80-frame linear speed ramp downward; REL is x = 10*cos(theta), theta += 2deg/tick.
// The non-Time ellipse setter moves immediately at t=0 (theta=0 => REL x=+10).
async sub cir01(x0: fx) {
    set_invuln(65535);
    set_hurtbox(14fx);            // source S:72 setHurtbox(28,28) -> source radius 14
    set_hitbox(8fx);              // source S:73 setHitbox(16,16) -> source radius 8

    // Source S:97-117 rank branches; Lunatic takes the !LO value, not Hard.
    var rank: int = global(GVAR_RANK);
    var n: int = 15;
    var speed: fx = 1.2fx;
    var shots: int = 1;
    var interval: int = 100;
    if rank == 1 { n = 25; speed = 1.8fx; shots = 3; interval = 80; }
    if rank == 2 { n = 30; speed = 1.8fx; shots = 3; interval = 70; }
    if rank == 3 { n = 42; speed = 2.3fx; shots = 3; interval = 70; }

    // t=0 source setters; apply the ellipse setter's immediate position change.
    move_to(0, x0 + 10fx, -32fx, EASE_LINEAR);
    var theta: angle = 0deg;
    var travel: fx = 0fx;
    // Arm source movement tick 1 for phase5 of this frame.
    theta = theta + 2deg;
    travel = travel + 4.35fx;
    move_vel_xy(0, (x0 + 10fx * cos(theta)) - $self_x,
        (-32fx + travel) - $self_y, EASE_LINEAR);

    // Source S:94-119 t=81 emitter configuration (etNew/etAim3/etSprite7,2).
    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, speed, 0fx);
    sh_dist(0, -4fx * speed);     // source ANIM a=1 S:119: position -= 4*velocity

    var t: int = 0;
    var next_shot: int = 81;      // source wait(80) then async first run on the next tick
    var left: int = shots;
    loop {
        wait(1);
        t = t + 1;
        // Source S:122-134: each shot redraws the ring base from RANDRAD, then fires.
        if t == next_shot && left > 0 {
            sh_angle(0, (rand(65536) as angle), 0deg);
            sh_fire(0);
            left = left - 1;
            next_shot = next_shot + interval;
        }
        // Arm source movement tick t+1. Tick 80 ends the speed ramp at 0.4.
        var k: int = t + 1;
        theta = theta + 2deg;
        if k <= 80 {
            travel = travel + (4.4fx - (k as fx) / 20fx);
        } else {
            travel = travel + 0.4fx;
        }
        move_vel_xy(0, (x0 + 10fx * cos(theta)) - $self_x,
            (-32fx + travel) - $self_y, EASE_LINEAR);
    }
}

// Source MainSub01 S:880-892: pair spawns at group-local 0/40/80/120.
async sub wave() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(170fx, -32fx, 1000, 0, 0, 0, cir01(170fx));
    _ = spawn_enemy(-170fx, -32fx, 1000, 0, 0, 0, cir01(-170fx));
    wait(40);
    _ = spawn_enemy(150fx, -32fx, 1000, 0, 0, 0, cir01(150fx));
    _ = spawn_enemy(-150fx, -32fx, 1000, 0, 0, 0, cir01(-150fx));
    wait(40);
    _ = spawn_enemy(130fx, -32fx, 1000, 0, 0, 0, cir01(130fx));
    _ = spawn_enemy(-130fx, -32fx, 1000, 0, 0, 0, cir01(-130fx));
    wait(40);
    _ = spawn_enemy(110fx, -32fx, 1000, 0, 0, 0, cir01(110fx));
    _ = spawn_enemy(-110fx, -32fx, 1000, 0, 0, 0, cir01(-110fx));
    wait(40);                     // group-local 160, as in S:891
    wait(320);                    // reach TIME_LIMIT: 360 source window + 120 tail
    loop { wait(600); }
}

// Training-only phase owner: placed at (0,0) and body-collision-off; real enemies keep source boxes.
async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
